var s=[{title:`Treinar com calor`,text:`O calor e a humidade podem fazer uma sessão fácil parecer muito mais difícil. Escolha as horas mais frescas e percursos à sombra, comece com suavidade e beba o suficiente para as condições. O CDC aconselha a parar e ir para um local fresco se se sentir tonto ou fraco. Confusão, desmaio ou suspeita de golpe de calor precisam de ajuda de emergência.`},{title:`Dias frios, húmidos e ventosos`,text:`Use camadas que possa tirar e cubra a pele exposta quando estiver frio. A chuva e o suor podem tornar a roupa e as superfícies perigosamente frias, e o frio intenso pode causar queimaduras pelo frio ou hipotermia. Gelo ou má visibilidade são uma boa razão para treinar em espaço fechado nesse dia.`},{title:`Verifique o terreno`,text:`Procure buracos, gravilha solta, raízes, pavimento irregular, má iluminação e passagens de estrada. As inclinações alteram a carga sobre os músculos e as articulações. Num percurso novo, comece a um ritmo confortável, dispense sprints a fundo e use calçado com boa aderência para a superfície.`},{title:`Verifique o equipamento do parque`,text:`Os bancos, as grades e as barras fixas podem estar desgastados, soltos ou não ser feitos para exercício dinâmico. Procure arestas afiadas, ferrugem, peças partidas e suportes instáveis. Não se pendure em nada a menos que seja claramente feito para o aguentar. Dê muito espaço aos ciclistas, às crianças e a outros utilizadores do parque.`},{title:`Verifique outra vez de cada vez`,text:`As condições ao ar livre mudam, por isso volte a olhar de cada vez que sair. Com mau tempo perigoso, mude para uma sessão em espaço fechado ou de baixo impacto e escolha percursos e movimentos que se adaptem à luz, ao terreno e à sua experiência.`}];var o=[{label:`CDC: exercício com calor`,url:`https://www.cdc.gov/heat-health/risk-factors/heat-and-athletes.html`},{label:`CDC: prevenir queimaduras pelo frio e hipotermia`,url:`https://www.cdc.gov/winter-weather/prevention/preventing-frostbite.html`},{label:`Recomendações do CDC sobre atividade física para adultos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:s,sources:o};export{r as default,s as sections,o as sources};